SIN_CLASIFICAR = {'ICT155-DOC-NORMA_PAGO_40': 'obliga por acreditacion, no por remision normativa: la tabla no sabe nombrar esa via y no se fuerza'}

def sellar(con, verbose: bool=False) -> dict:
    """Public CI documentation."""
    puestas = muertos = sin_obra = 0
    for ident, (clase, fundamento, _) in TABLA.items():
        fila = con.execute('SELECT id FROM obra WHERE identificador_canonico = ?', (ident,)).fetchone()
        if fila is None:
            sin_obra += 1
            continue
        obra_f, _, ruta = fundamento.partition('::')
        existe = con.execute('\n            SELECT 1 FROM precepto p\n            JOIN version v ON v.id = p.version_id\n            JOIN obra o    ON o.id = v.obra_id\n            WHERE o.identificador_canonico = ? AND p.ruta_estructural = ?', (obra_f, ruta)).fetchone()
        if existe is None:
            muertos += 1
            continue
        con.execute('UPDATE obra SET caracter_juridico = ?, caracter_juridico_fundamento = ? WHERE id = ?', (clase, fundamento, fila['id']))
        puestas += 1
    if verbose:
        print(f'caracter juridico grabado: {puestas} obras' + (f'  |  fundamento que no resuelve: {muertos}' if muertos else '') + (f'  |  sin obra: {sin_obra}' if sin_obra else '') + f'  |  sin clasificar a proposito: {len(SIN_CLASIFICAR)}')
    return {'puestas': puestas, 'muertos': muertos, 'sin_obra': sin_obra, 'sin_clasificar': len(SIN_CLASIFICAR)}
